steps.text:
s=>{
        const isFei=(s.ranks?.zhou==='妃');
        return isFei?[
          `双生的赏单送到凤仪宫时，周清漪已经是妃位。顾明宜没有再夹晋位折，只把产后月例、二公主乳母和绮春宫用度分开列清。`,
          `“她已经晋过。”顾明宜道，“生下皇嗣，不必再拿位分补一次。”`,
          `这一笔只剩赏赐，没有第二次晋封。`
        ]:[
          `双生的赏单送到凤仪宫，顾明宜另外夹了一张空白晋位折。`,
          `周清漪仍是嫔位。生下公主、又经历那一夜，并不等于她一定要升。`,
          `顾明宜只写：“周嫔资序已足，可议晋一级。”`,
          `要不要从嫔到妃，仍由我决定。`
        ];
      }

s=>{
        const isFei=s.ranks?.zhou==='妃';
        return isFei?[
          `周清漪还在绮春宫休养，没有来请安。凤仪宫却得先把她日后复请安的位置改出来。`,
          `顾明宜让人把周妃那把椅子往前挪了一席，又特意空着，不许旁人临时坐。`,
          `有人说人还没来，何必现在改。顾明宜只道：“旨意已经到了。她坐不坐是身体的事，位置不能等她来了再临时找。”`,
          `沈知微看了一眼那把空椅子，没有说话。`
        ]:[
          `周清漪还在绮春宫休养，没有来请安。凤仪宫照旧排座次，她的位置也仍在原处。`,
          `有人私下觉得她生了公主，又经历双生，怎么也该往前挪一席。顾明宜只看了一眼座次册：“旨意没动，本宫不能自己替她升。”`,
          `沈知微来时只问周清漪伤口还疼不疼。宫人说她总答“不疼”。沈知微道：“那便别问她，问太医。”`
        ];
      }

s=>{
        const mode=s.flags?.sistersResidence;
        let first='';
        if(mode==='together') first=`同住以后，拾遗阁最先变的是饭桌。抱朴三天两头改菜单，含章从不管，但辣椒太多时会默默换一壶清茶。夜里两人的宫女都从同一道门进出。`;
        else if(mode==='split') first=`左右分院以后，白日里像两户人家，到了晚饭又常有人从一边端碗去另一边。抱朴最常忘记先通报，含章也从没真让人把她拦在门外。`;
        else if(mode==='separate') first=`含章迁去听竹馆以后，两姐妹见面反而开始约时辰。抱朴隔几日过去吃晚饭，含章偶尔也回拾遗阁坐一会儿。以前抬脚就能见的人，如今第一次需要“特意去见”。`;
        else first=`住处还在重新分配，两姐妹已经先把自己的东西一点点摆进宫里。`;
        return [
          first,
          `顾明宜送过一次春衣。抱朴嫌袖口窄，直接让尚衣局改；含章那套没有动，只把腰带换短一点。`,
          `沈知微第一次在请安时真正和她们说上话。她的目光在两人发间的旧国银簪上停了一瞬，只问：“北边冷，住得惯么？”没有追问蘅国。`,
          `抱朴很快记住哪位嬷嬷嘴硬心软、哪宫送来的点心需要当天回礼。含章仍不大往人多的地方去，偶尔借书，偶尔一个人在御花园坐一会儿。`,
          `有一回两人在海棠树下争一枝花。抱朴说折回去插瓶，含章说树上更好看。最后谁也没折。第二日花被风吹落，抱朴捡回来放在窗边，含章看见，也没有说什么。`,
          `月底请安，已经不用宫人提醒她们从哪边进殿。周清漪只把手边椅子往外挪了半寸，给她们让路，仍接着方才的话说下去。`
        ];
      }

s=>{
    const x=s?.flags?.extraHeirs?.[1];
    if(!x||x.skipped)return ['五月没有新的产报。尚宫局把预备的乳母牌收回柜里，皇后只叫太医院照旧请平安脉。'];
    const name=PEOPLE?.[x.mother]?.name||'生母';
    const rank=String(s?.ranks?.[x.mother]||'');
    const next={答应:'常在',常在:'贵人',贵人:'嫔'}[rank.match(/(答应|常在|贵人)$/)?.[1]||''];
    const mother=rank?`${name}（${rank}）`:name;
    return [
      `五月天刚亮，${mother}宫里传出婴啼。女医先报母体平安，过了一会儿才把孩子抱到灯下细看。`,
      `${mother}累得睁不开眼，仍撑着问了一句：“哭得响不响？”乳母说响，她才松开一直攥着的床单。`,
      `玉牒房午后来核名，纸上写着“${x.order||'皇嗣'}·${String(x.name||'').replace(/^杨/,'')}”。皇后看过乳母与夜值名单，叫人把孩子腕上的红绳松半指。`,
      next?`同日另下产育册旨，${mother}晋一级。传旨时她没起身，只在枕上谢恩，随后问孩子什么时候抱回来吃奶。`:`洗三与满月仍照常预备。太后另送来一床薄绫小被。`
    ];
  }

s=>{
    const names=childNames(s);
    return [
      '九月下旬，皇嗣院也传来坏消息。玉牒房来问姓名时，太后只说：“先让母亲看过孩子，再来问纸。”',
      names.length?`玉牒上待记的，是${names.join('、')}的名字。来取回小衣的乳母抱着衣裳站在门外，没有立刻上车。`:'皇嗣院仍撤下一张小床。来取回小衣的乳母抱着衣裳站在门外，没有立刻上车。',
      '令兮把屋里的布偶挑了两只送过去，说谁夜里哭就给谁。三皇子听见死讯只说知道了，那日在上书房射箭，却连续三箭脱靶。顾明宜让教习停课，没有让这件事进东所日记。',
      '我将太医留下，问剩下的几个能不能好。他说药已换过，今晚还须守。我问还有没有别的方，他跪下来，说有几味不敢贸然用。',
      '“朕让你治，不是让你守着。”这句话一出口，裴景和便低下头。太医没有辩，只将今日的脉案送到我手边，几处涂改还未干。',
      '我没有再问他为何不敢用，叫人先送饭，又准他将另一名老医官请来同看。两人在廊下低声争了一阵，没有谁说有把握。',
      '夜里裴景和报孩子喝下了两口水。我问是不是好些，他答太医尚未这样说。案上的旨意已经发出去，我又坐了一刻，将明早要问的名字写在纸边。'
    ];
  }

s=>{
    const victim=s.flags?.v46LowVictim,n=victim?PEOPLE[victim]?.name:'一名低位宫嫔',kids=childNames(s);
    return [
      '十二月初，储秀宫西院先开一扇门。素荷抱着晒过的被褥出来，在门槛上停了片刻。有人想替她抱，她摇头，说自己拿得动，走了几步又停下来换手。',
      `<span class="v46-epidemic-ledger"><b>疫后内廷薄册</b>顾皇后薨；许氏卒；${n}卒；${kids.length?kids.join('、')+'薨；':''}宫人、内监另有死者。病愈者陆续复值。</span>`,
      '外门要开时，守门人仍问太医院能不能再等两日。尚有病人的院子没有跟着开，送药的篮子照旧从窄路进去。邵明贞逐处定下值守，没有去坐凤仪宫正座。',
      '宫门开了，第一封家信送进来，城南那个内侍蹲在值房外读。信里没有报喜，只说家里还在做饭，让他放心。他折好纸，坐了一会儿才起来。',
      '西夹道石阶扫净，檐下重新挂了宫灯。提食盒的人换了一班，走到旧日歇脚的柱旁，问哪一道门还要送。素荷给她指了路，自己抱着被褥往前走。',
      '她走过那盏灯时，前头食盒里的匙碰响了。一名宫女回过头，等她赶上来，两个人并着走完余下那段路。'
    ];
  }

s=>{
      const value=typeof old==='function'?old(s):old;
      const lines=Array.isArray(value)?value:[value];
      return lines.map(line=>String(line)
        .replace('她把茶放下，走到我面前。墙上的两道影子因为她走近，慢慢叠到一处。','她把茶放下，走到我面前，在半臂外停住，先问：“我能替你把鬓边的头发拢好吗？”')
        .replace('我应该后退。这个判断很清楚，甚至不需要写进任何册子。可我没有动。','我点了点头。')
        .replace('她走近时，我知道自己该退一步，可我没有动。','我点了点头。')
        .replace('她的指尖最后只碰到我鬓边，把一缕不知什么时候散下来的头发拢到耳后。很轻。','她这才伸手，把一缕散下来的头发拢到我耳后。指尖很轻，很快便收回去。')
        .replace('这件事最不应该发生在我身上。可我没有去回想。','我没有躲，也没有把这件事说成无意。')
      );
    }

